head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.vScrenID = "ULDSTF05962.xml";
scwin.vScrenTpCD = "";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.pIndex;
scwin.TR_JOB;
scwin.vIsurCd, scwin.vIsurNm, scwin.vInputRnd, scwin.vTrJob;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
    }
};
scwin.fn_read_sync = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral&outputMessageId=HDNCHAMP_MGM_INOUT";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&queryId=lds.stf.lstproc.hdnchamp.select";
    url += "&{P}param01=" + scwin.vIsurCd;
    url += "&{P}param02=" + scwin.vInputRnd;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사명]를 입력하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_SECT_AHTH_QUAL_CONTN) == "") {
        $c.win.alert("[라이징스타 인증자격]을 입력하세요.");
        txb_SECT_AHTH_QUAL_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_SECT_AHTH_INST_NM) == "") {
        $c.win.alert("[라이징스타 인증기관]을 입력하세요.");
        txb_SECT_AHTH_INST_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_DESIGN_DD_1) == "") {
        $c.win.alert("[라이징스타 지정일자]를 입력하세요.");
        edt_DESIGN_DD_1.focus();
        return false;
    }
    return true;
};
scwin.fn_SetValue = function() {
    dts_Item.setCellData(1, "PINDEX", scwin.pIndex);
    dts_Item.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
    dts_Item.setCellData(1, "INPUT_RND", scwin.vInputRnd);
    dts_Item.setCellData(1, "SECT_AHTH_QUAL_CONTN", $c.stf.getObjectValue(txb_SECT_AHTH_QUAL_CONTN));
    dts_Item.setCellData(1, "SECT_AHTH_INST_NM", $c.stf.getObjectValue(txb_SECT_AHTH_INST_NM));
    /*	dts_Item.setNameValue(1, "RESRH_DEV_INVST_RTO",getObjectValue(txb_RESRH_DEV_INVST_RTO))        ;
    dts_Item.setNameValue(1, "ACNTG_CORP_REVW_CONTN",getObjectValue(txb_ACNTG_CORP_REVW_CONTN)) ;
    dts_Item.setNameValue(1, "PRSNT_SECT_DESIGN_DD",getObjectValue(edt_PRSNT_SECT_DESIGN_DD))      ;
    dts_Item.setNameValue(1, "SECT_AHTH_CONTN",getObjectValue(txb_SECT_AHTH_CONTN))               ;*/
    dts_Item.setCellData(1, "DESIGN_DD_1", $c.stf.getObjectValue(edt_DESIGN_DD_1));
    dts_Item.setCellData(1, "REMK_1", $c.stf.getObjectValue(txa_REMK_1));
    dts_Item.setCellData(1, "REG_ID", js_emp_no);
};
scwin.fn_trs = function() {
    scwin.fn_SetValue();
    scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    trs_Save.Action = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveRisingStar";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.fn_save = function() {
    scwin.TR_JOB = scwin.vTrJob;
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        //dts_Item.UserStatus(1) = TB_JOB_INSERT;
        scwin.fn_trs();
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) {

        //dts_Del.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_Del.insertRow();
        dts_Del.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
        dts_Del.setCellData(1, "INPUT_RND", scwin.vInputRnd);
        dts_Del.setCellData(1, "REG_ID", js_emp_no);
        trs_Delete.Action = "/SectionTypeChange.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=deleteRisingStar";
        trs_Delete.KeyValue = "JSP(I:pInput=dts_Del)";
        trs_Delete.Post();
    }
};
scwin.fn_parentRefresh = async function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
    await $c.frame.CloseFrame();
};
scwin.img_COM_NM_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
};
scwin.txb_ISUR_CD_onblur = function() {
    if (txb_ISUR_CD.getValue() == "") {
        txb_COM_NM.setValue("");
    }
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_parentRefresh();
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.btn_DESIGN_DD_1_onclick = function() {
    popUpCalendar2(edt_DESIGN_DD_1);
};
scwin.gform_onload = function() {
    scwin.pIndex = $c.stf.getQuery(frame.srcUrl, "nIndex");
    dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=HDNCHAMP_MGM_INOUT";
    dts_Item.reset();
    dts_Item.insertRow();
    var parentWin = $c.frame.path("../");
    scwin.vIsurCd = parentWin.gIsurCd;
    scwin.vIsurNm = parentWin.gIsurNm;
    scwin.vInputRnd = parentWin.gInputRnd;
    scwin.vTrJob = parentWin.gGubnStat;
    if (scwin.vTrJob == "U") {
        //alert("vIsurCd:"+vIsurCd + " vIsurNm:"+vIsurNm+" vInputRnd:"+vInputRnd+" vTrJob:"+vTrJob);
        $c.stf.setObjectValue(txb_ISUR_CD, scwin.vIsurCd);
        $c.stf.setObjectValue(txb_COM_NM, scwin.vIsurNm);
        txb_ISUR_CD.setReadOnly(true);
        img_COM_NM.src = "../img/btn_search_d.gif";
        img_COM_NM.setDisabled(true);
        btn_save.src = "../img/btn_save_d.gif";
        btn_save.setDisabled(true);
        scwin.fn_read_sync();
    } else {
        //I
        scwin.vIsurCd = "";
        scwin.vIsurNm = "";
        scwin.vInputRnd = "";
        btn_update.src = "../img/btn_modify_d.gif";
        btn_update.setDisabled(true);
    }
};
scwin.btn_update_onclick = function() {
    scwin.fn_save();
};
scwin.btn_delete_onclick = function() {
    scwin.fn_delete();
};
scwin.trs_Delete_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    var parentWin = $c.frame.path("../");
    parentWin.fn_list_sync();
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
